export interface Event extends LlmResponse {
  id: string;
  invocationId: string;
  author?: string;
  actions: EventActions;
  longRunningToolIds?: string[];
  branch?: string;
  timestamp: number;
}

export interface EventActions {
  skipSummarization?: boolean;
  stateDelta: {[key: string]: unknown};
  artifactDelta: {[key: string]: number};
  transferToAgent?: string;
  escalate?: boolean;
  requestedAuthConfigs: {[key: string]: AuthConfig};
  requestedToolConfirmations: {[key: string]: ToolConfirmation};
}

export function isFinalResponse(event: Event) {
  if (
    event.actions.skipSummarization ||
    (event.longRunningToolIds && event.longRunningToolIds.length > 0)
  ) {
    return true;
  }
  return (
    getFunctionCalls(event).length === 0 &&
    getFunctionResponses(event).length === 0 &&
    !event.partial &&
    !hasTrailingCodeExecutionResult(event)
  );
}

export function stringifyContent(event: Event): string {
  if (!event.content?.parts) {
    return '';
  }
  return event.content.parts.map((part) => part.text ?? '').join('');
}

function createBranchCtxForSubAgent(
  agent: BaseAgent,
  subAgent: BaseAgent,
  originalContext: InvocationContext,
): InvocationContext {
  const invocationContext = new InvocationContext(originalContext);
  const branchSuffix = `${agent.name}.${subAgent.name}`;
  invocationContext.branch = invocationContext.branch
    ? `${invocationContext.branch}.${branchSuffix}`
    : branchSuffix;
  return invocationContext;
}

