export function mergeEventActions(
  sources: Array<Partial<EventActions>>,
  target?: EventActions,
): EventActions {
  const result = createEventActions();
  if (target) {
    Object.assign(result, target);
  }
  for (const source of sources) {
    if (!source) continue;
    if (source.stateDelta) {
      Object.assign(result.stateDelta, source.stateDelta);
    }
    if (source.artifactDelta) {
      Object.assign(result.artifactDelta, source.artifactDelta);
    }
    if (source.requestedAuthConfigs) {
      Object.assign(result.requestedAuthConfigs, source.requestedAuthConfigs);
    }
    if (source.requestedToolConfirmations) {
      Object.assign(
        result.requestedToolConfirmations,
        source.requestedToolConfirmations,
      );
    }
    if (source.skipSummarization !== undefined) {
      result.skipSummarization = source.skipSummarization;
    }
    if (source.transferToAgent !== undefined) {
      result.transferToAgent = source.transferToAgent;
    }
    if (source.escalate !== undefined) {
      result.escalate = source.escalate;
    }
  }
  return result;
}

async *runAsync(params: {
  userId: string;
  sessionId: string;
  newMessage: Content;
  stateDelta?: Record<string, unknown>;
  runConfig?: RunConfig;
}): AsyncGenerator<Event, void, undefined> {
  // ... setup span and context ...
  const session = await this.sessionService.getSession({
    appName: this.appName,
    userId,
    sessionId,
  });
  // ... validate CFC support ...
  const invocationContext = new InvocationContext({...});
  // ... plugin user message callback ...
  if (newMessage) {
    // ... save artifacts if needed ...
    await this.sessionService.appendEvent({...});
  }
  invocationContext.agent = this.determineAgentForResumption(
    session,
    this.agent,
  );
  const beforeRunCallbackResponse =
    await this.pluginManager.runBeforeRunCallback({...});
  if (beforeRunCallbackResponse) {
    // ... early exit ...
  } else {
    for await (const event of invocationContext.agent.runAsync(
      invocationContext,
    )) {
      if (!event.partial) {
        await this.sessionService.appendEvent({session, event});
      }
      const modifiedEvent =
        await this.pluginManager.runOnEventCallback({...});
      yield modifiedEvent || event;
    }
    await this.pluginManager.runAfterRunCallback({...});
  }
}

private determineAgentForResumption(
  session: Session,
  rootAgent: BaseAgent,
): BaseAgent {
  // Case 1: Function response matching
  const event = findEventByLastFunctionResponseId(session.events);
  if (event && event.author) {
    return rootAgent.findAgent(event.author) || rootAgent;
  }
  // Case 2: Last-agent-with-transfer-ability
  for (let i = session.events.length - 1; i >= 0; i--) {
    const event = session.events[i];
    if (event.author === 'user' || !event.author) {
      continue;
    }
    if (event.author === rootAgent.name) {
      return rootAgent;
    }
    const agent = rootAgent.findSubAgent(event.author!);
    if (!agent) {
      continue;
    }
    if (this.isRoutableLlmAgent(agent)) {
      return agent;
    }
  }
  // Case 3: default to root
  return rootAgent;
}

private isRoutableLlmAgent(agentToRun: BaseAgent): boolean {
  let agent: BaseAgent | undefined = agentToRun;
  while (agent) {
    if (!isLlmAgent(agent)) {
      return false;
    }
    if (agent.disallowTransferToParent) {
      return false;
    }
    agent = agent.parentAgent;
  }
  return true;
}

