private async runCallbacks(
  plugins: Set<BasePlugin>,
  callback: (plugin: BasePlugin) => Promise<unknown>,
  callbackName: string,
): Promise<unknown> {
  for (const plugin of plugins) {
    try {
      const result = await callback(plugin);
      if (result !== undefined) {
        logger.debug(
          `Plugin '${plugin.name}' returned a value for callback '${callbackName}', exiting early.`,
        );
        return result;
      }
    } catch (e) {
      const errorMessage = `Error in plugin '${plugin.name}' during '${callbackName}' callback: ${e}`;
      logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  return undefined;
}

export enum PolicyOutcome {
  DENY = 'DENY',
  CONFIRM = 'CONFIRM',
  ALLOW = 'ALLOW',
}

export interface BasePolicyEngine {
  evaluate(context: ToolCallPolicyContext): Promise<PolicyCheckResult>;
}

override async beforeToolCallback({tool, toolArgs, toolContext}: {...}): Promise<{[key: string]: unknown} | undefined> {
  const toolCallCheckState = this.getToolCallCheckState(toolContext);

  // Check policy ONCE on first call
  if (!toolCallCheckState) {
    return this.checkToolCallPolicy({tool, toolArgs, toolContext});
  }

  // Handle CONFIRM outcome on subsequent calls
  if (toolCallCheckState !== PolicyOutcome.CONFIRM) {
    return;
  }

  if (!toolContext.toolConfirmation) {
    return {partial: INTERMEDIATE_REQUIRE_TOOL_CALL_CONFIRMATION_ERROR};
  }

  this.setToolCallCheckState(toolContext, toolContext.toolConfirmation);
  if (!toolContext.toolConfirmation.confirmed) {
    return {error: 'Tool call rejected from confirmation flow.'};
  }
  toolContext.toolConfirmation = undefined;
  return;
}

private async checkToolCallPolicy({tool, toolArgs, toolContext}: {...}): Promise<{[key: string]: unknown} | undefined> {
  const policyCheckResult = await this.policyEngine.evaluate({tool, toolArgs});

  this.setToolCallCheckState(toolContext, policyCheckResult.outcome);

  switch (policyCheckResult.outcome) {
    case PolicyOutcome.DENY:
      return {error: `This tool call is rejected by policy engine. Reason: ${policyCheckResult.reason}`};
    case PolicyOutcome.CONFIRM:
      toolContext.requestConfirmation({
        hint: `Policy engine requires confirmation calling tool: ${tool.name}. Reason: ${policyCheckResult.reason}`,
      });
      return {partial: INTERMEDIATE_REQUIRE_TOOL_CALL_CONFIRMATION_ERROR};
    case PolicyOutcome.ALLOW:
      return;
    default:
      return;
  }
}

