export class PluginManager {
  private readonly plugins: Set<BasePlugin> = new Set();

  constructor(plugins?: BasePlugin[]) {
    if (plugins) {
      for (const plugin of plugins) {
        this.registerPlugin(plugin);
      }
    }
  }

  registerPlugin(plugin: BasePlugin): void {
    // Short circuit for duplicate objects or duplicate names
    if (this.plugins.has(plugin)) {
      throw new Error(`Plugin '${plugin.name}' already registered.`);
    }
    if (Array.from(this.plugins).some((p) => p.name === plugin.name)) {
      throw new Error(`Plugin with name '${plugin.name}' already registered.`);
    }

    this.plugins.add(plugin);
    logger.info(`Plugin '${plugin.name}' registered.`);
  }
}

private async runCallbacks(
  plugins: Set<BasePlugin>,
  callback: (plugin: BasePlugin) => Promise<unknown>,
  callbackName: string,
): Promise<unknown> {
  for (const plugin of plugins) {
    try {
      const result = await callback(plugin);
      if (result !== undefined) {
        logger.debug(
          `Plugin '${plugin.name}' returned a value for callback '${callbackName}', exiting early.`,
        );
        return result;  // Short-circuit with replacement
      }
      // If undefined returned, continue with (potentially modified) original
    } catch (e) {
      const errorMessage = `Error in plugin '${plugin.name}' during '${callbackName}' callback: ${e}`;
      logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  return undefined;
}

/**
 * Callback executed when a model call encounters an error.
 *
 * This callback provides an opportunity to handle model errors gracefully,
 * potentially providing alternative responses or recovery mechanisms.
 *
 * @param params.callbackContext The context for the current agent call.
 * @param params.llmRequest The request that was sent to the model when the error
 *     occurred.
 * @param params.error The exception that was raised during model execution.
 * @returns An optional LlmResponse. If an LlmResponse is returned, it will be
 *     used instead of propagating the error. Returning `undefined` allows
 *     the original error to be raised.
 */
async onModelErrorCallback(params: {
  callbackContext: CallbackContext;
  llmRequest: LlmRequest;
  error: Error;
}): Promise<LlmResponse | undefined> {
  return;
}

async runOnModelErrorCallback({
  callbackContext,
  llmRequest,
  error,
}: {
  callbackContext: CallbackContext;
  llmRequest: LlmRequest;
  error: Error;
}): Promise<LlmResponse | undefined> {
  return (await this.runCallbacks(
    this.plugins,
    (plugin: BasePlugin) =>
      plugin.onModelErrorCallback({callbackContext, llmRequest, error}),
    'onModelErrorCallback',
  )) as LlmResponse | undefined;
}
